/* Deploy Function SFin.tvf_InvoiceAutomation_Phase3Detections using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Functions\SFin.tvf_InvoiceAutomation_Phase3Detections.sql */
/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R7C4 selected DEV schema source sync
    Object             : Function SFin.tvf_InvoiceAutomation_Phase3Detections
    Source schema hash : 42EEA565CDAD4821813504920C552D8195AE51BB41A0F46299DC7FE84A387690
    Definition SHA-256 : 669B6AFB9C3F6187B225BDAB603BC76CB9410D96463D6439D6C4D31EC119A509

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*
    Permanent correction for trigger-instance automation.
    The active Phase 3 path has its own eligibility test, so it must use the
    same authoritative rules as the blocking diagnostics view.
*/
CREATE OR ALTER FUNCTION [SFin].[tvf_InvoiceAutomation_Phase3Detections]()
RETURNS TABLE
AS
RETURN
WITH ScheduleJobScope AS
(
    SELECT DISTINCT
          sch.ID AS InvoiceScheduleId
        , sch.Guid AS InvoiceScheduleGuid
        , qi.CreatedJobId AS JobId
    FROM SSop.QuoteItems AS qi
    INNER JOIN SFin.InvoiceSchedules AS sch
        ON sch.ID = qi.InvoicingSchedule
    WHERE qi.RowStatus NOT IN (0, 254)
      AND sch.RowStatus NOT IN (0, 254)
      AND qi.CreatedJobId NOT IN (-1, 0)
      AND qi.InvoicingSchedule NOT IN (-1, 0)
),
EligibleScope AS
(
    SELECT
          sjs.InvoiceScheduleId
        , sjs.InvoiceScheduleGuid
        , sjs.JobId
        , CAST
          (
              CASE
                  WHEN j.InvoiceProcessingMode IN (1, 2) THEN 1
                  WHEN ISNULL(j.CannotBeInvoiced, 0) = 1 THEN 1
                  WHEN ISNULL(acs.IsHold, 0) = 1 THEN 1
                  ELSE 0
              END
              AS BIT
          ) AS IsBlocked
        , sch.ActivityMilestoneConfigurationId
        , sch.RibaConfigurationId
    FROM ScheduleJobScope AS sjs
    INNER JOIN SFin.InvoiceSchedules AS sch
        ON sch.ID = sjs.InvoiceScheduleId
       AND sch.RowStatus NOT IN (0, 254)
    INNER JOIN SJob.Jobs AS j
        ON j.ID = sjs.JobId
       AND j.RowStatus NOT IN (0, 254)
    LEFT JOIN SCrm.Accounts AS a
        ON a.ID = j.FinanceAccountID
       AND a.RowStatus NOT IN (0, 254)
    LEFT JOIN SCrm.AccountStatus AS acs
        ON acs.ID = a.AccountStatusID
       AND acs.RowStatus NOT IN (0, 254)
)

/* Activities: billable and complete. */
SELECT
      es.InvoiceScheduleId
    , es.InvoiceScheduleGuid
    , es.JobId
    , CAST(N'Activity' AS NVARCHAR(50)) AS InstanceType
    , CAST(N'ACT:' + CONVERT(NVARCHAR(50), act.ID) AS NVARCHAR(200)) AS InstanceKey
    , CAST(COALESCE(act.CompletedDateTimeUTC, act.EndDate) AS DATETIME2(7)) AS CompletedDateTimeUTC
FROM EligibleScope AS es
INNER JOIN SJob.Activities AS act
    ON act.JobID = es.JobId
   AND act.RowStatus NOT IN (0, 254)
INNER JOIN SJob.ActivityTypes AS aty
    ON aty.ID = act.ActivityTypeID
INNER JOIN SJob.ActivityStatus AS ats
    ON ats.ID = act.ActivityStatusID
LEFT JOIN SFin.InvoiceScheduleActivityMilestoneConfiguration AS amc
    ON amc.ID = es.ActivityMilestoneConfigurationId
   AND amc.RowStatus NOT IN (0, 254)
WHERE es.IsBlocked = 0
  AND aty.IsBillable = 1
  AND ats.IsCompleteStatus = 1
  AND ISNULL(act.InvoicingValue, 0) > 0
  AND COALESCE(act.CompletedDateTimeUTC, act.EndDate) IS NOT NULL
  AND
  (
      amc.ID IS NULL
      OR ISNULL(amc.OnActivityCompletion, 0) = 1
      OR ISNULL(amc.OnActivityAndMilestonCompletion, 0) = 1
  )

UNION ALL

/* Milestones: complete and applicable. */
SELECT
      es.InvoiceScheduleId
    , es.InvoiceScheduleGuid
    , es.JobId
    , CAST(N'Milestone' AS NVARCHAR(50)) AS InstanceType
    , CAST(N'MS:' + CONVERT(NVARCHAR(50), m.ID) AS NVARCHAR(200)) AS InstanceKey
    , m.CompletedDateTimeUTC AS CompletedDateTimeUTC
FROM EligibleScope AS es
INNER JOIN SJob.Milestones AS m
    ON m.JobID = es.JobId
   AND m.RowStatus NOT IN (0, 254)
LEFT JOIN SFin.InvoiceScheduleActivityMilestoneConfiguration AS amc
    ON amc.ID = es.ActivityMilestoneConfigurationId
   AND amc.RowStatus NOT IN (0, 254)
WHERE es.IsBlocked = 0
  AND ISNULL(m.IsNotApplicable, 0) = 0
  AND ISNULL(m.IsComplete, 0) = 1
  AND m.CompletedDateTimeUTC IS NOT NULL
  AND
  (
      amc.ID IS NULL
      OR ISNULL(amc.OnMilestoneCompletion, 0) = 1
      OR ISNULL(amc.OnActivityAndMilestonCompletion, 0) = 1
  )

UNION ALL

/* RIBA stages: retain the current completion behaviour. */
SELECT
      es.InvoiceScheduleId
    , es.InvoiceScheduleGuid
    , es.JobId
    , CAST(N'RIBA' AS NVARCHAR(50)) AS InstanceType
    , CAST(N'RIBA:' + CONVERT(NVARCHAR(50), js.ID) AS NVARCHAR(200)) AS InstanceKey
    , COALESCE(js.CompletedDateTimeUTC, js.EndDateTime) AS CompletedDateTimeUTC
FROM EligibleScope AS es
INNER JOIN SJob.JobStages AS js
    ON js.JobID = es.JobId
   AND js.RowStatus NOT IN (0, 254)
WHERE es.IsBlocked = 0
  AND COALESCE(js.CompletedDateTimeUTC, js.EndDateTime) IS NOT NULL;
GO

GO

/* Deploy Function SFin.tvf_InvoiceRequestsValidate using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Functions\SFin.tvf_InvoiceRequestsValidate.sql */
/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R7C4 selected DEV schema source sync
    Object             : Function SFin.tvf_InvoiceRequestsValidate
    Source schema hash : 5376F34C611594327432DF8A490C4CA11686E1EA673A6B8ADF4A8C517E97CBFB
    Definition SHA-256 : 085C8094DAE53A38404712A40AD741B35C63F70E450DAC595100FC31524A517F

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE OR ALTER FUNCTION [SFin].[tvf_InvoiceRequestsValidate]
(
    @Guid				UNIQUEIDENTIFIER,
	@IsWIP				BIT,
	@WIPReason			NVARCHAR(MAX)
)
RETURNS @ValidationResult TABLE
(
    ID INT IDENTITY(1, 1) NOT NULL,
    TargetGuid UNIQUEIDENTIFIER NOT NULL DEFAULT ('00000000-0000-0000-0000-000000000000'),
    TargetType CHAR(1) NOT NULL DEFAULT (''),
    IsReadOnly BIT NOT NULL DEFAULT ((0)),
    IsHidden BIT NOT NULL DEFAULT ((0)),
    IsInvalid BIT NOT NULL DEFAULT ((0)),
    [IsInformationOnly] [BIT] NOT NULL DEFAULT ((0)),
    Message NVARCHAR(2000) NOT NULL DEFAULT ('')
)
AS
BEGIN

	/*
		If the invoice request is set to WIP,
		ensure there is a reason added.
	*/
	IF(@IsWIP = 1 AND @WIPReason = N'')
		BEGIN
				INSERT @ValidationResult
				(TargetGuid, TargetType, IsReadOnly, IsHidden, IsInvalid, Message)
			SELECT
				epfvv.Guid,
				N'P',
				0,
				0,
				1,
				N'You must enter a reason.'
			FROM SCore.EntityPropertiesForValidationV AS epfvv
			WHERE epfvv.[Schema] = N'SFin'
				AND epfvv.Hobt = N'InvoiceRequests'
				AND epfvv.Name IN (N'WIPReason');
		END;




			

    RETURN;
END;
GO

GO

