    Object             : Function SOffice.tvf_FrequentFilingRecords
    Source schema hash : 708CB8FF88DB27F3269C7743751852B52879E7105A333BA1117BAC07FF76E47D
    Definition SHA-256 : 84710DA3DECB32D43175D86BBCE301DC8F0046F0450B875207E95A1D7294E1A2

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE OR ALTER FUNCTION [SOffice].[tvf_FrequentFilingRecords]
    (
        @Mailbox NVARCHAR(250),
        @WindowStart DATETIME2
    )
RETURNS TABLE
AS
RETURN
    (
        SELECT TOP (20)
                    t.ID,
                    t.Guid,
                    et.Name                 AS EntityTypeName,
                    t.Name,
                    COUNT(*)                AS FiledCount,
                    MAX(oe.FiledDateTime)   AS LastFiledDateTime
        FROM        SOffice.OutlookEmails AS oe
        JOIN        SOffice.OutlookEmailMailboxes AS mb ON (mb.ID = oe.OutlookEmailMailboxID)
        JOIN        SOffice.TargetObjects AS t ON (t.ID = oe.TargetObjectID)
        JOIN        SOffice.EntityTypes AS et ON (et.ID = t.EntityTypeId)
        WHERE       (oe.RowStatus NOT IN (0, 254))
                AND (t.RowStatus NOT IN (0, 254))
                AND (et.RowStatus NOT IN (0, 254))
                AND (oe.IsFiled = 1)
                AND (oe.FiledDateTime >= @WindowStart)
                AND (mb.Name = @Mailbox)
                AND (@Mailbox <> N'')
        GROUP BY    t.ID,
                    t.Guid,
                    et.Name,
                    t.Name
        ORDER BY    COUNT(*) DESC,
                    MAX(oe.FiledDateTime) DESC
    );
GO

GO

/* Deploy Function SSop.tvf_QuotesDataPills using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Functions\SSop.tvf_QuotesDataPills.sql */
/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R7C4 selected DEV schema source sync
    Object             : Function SSop.tvf_QuotesDataPills
    Source schema hash : 9380FA8409ABD3A775CF86E6FF7A0C0AD8BC9D9F4BDB796341B0B5123643ED26
    Definition SHA-256 : 1D1C86EE3C198D970D3F8A35B8C345EAB65C05BB8C56B502024F374DF1A55FE6

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE OR ALTER FUNCTION [SSop].[tvf_QuotesDataPills]
(
    @Guid                UNIQUEIDENTIFIER,
    @DateAccepted        DATE,
    @DateRejected        DATE,
    @ProjectGuid         UNIQUEIDENTIFIER,
    @ContractGuid        UNIQUEIDENTIFIER,
    @AgentContractGuid   UNIQUEIDENTIFIER
)
RETURNS @DataPills TABLE
(
    [ID]        [INT]        IDENTITY (1, 1) NOT NULL,
    [Label]     NVARCHAR(50) NOT NULL,
    [Class]     NVARCHAR(50) NOT NULL,
    [SortOrder] INT          NOT NULL
)
   --WITH SCHEMABINDING
AS
BEGIN

    -------------------------------------------------------------------------
    -- NDA (existing behaviour preserved)
    -------------------------------------------------------------------------
    DECLARE @IsSubjectToNDA BIT;
    DECLARE @ProjectID INT;

    SELECT @ProjectID = p.ID
    FROM SSop.Projects AS p
    WHERE p.Guid = @ProjectGuid;

    SELECT @IsSubjectToNDA = e.IsSubjectToNDA
    FROM SSop.Enquiries AS e
    WHERE e.ProjectId = @ProjectID;

    IF (@IsSubjectToNDA = 1)
    BEGIN
        INSERT @DataPills (Label, Class, SortOrder)
        VALUES (N'NDA', N'bg-danger', 1);
    END

    -------------------------------------------------------------------------
    -- Canonical workflow status GUIDs (locked rules)
    -------------------------------------------------------------------------
    DECLARE @ReadyToSendGuid UNIQUEIDENTIFIER = CONVERT(UNIQUEIDENTIFIER, '02A2237F-2AE7-4E05-926F-38E8B7D050A0'); -- ID 14
    DECLARE @SentGuid        UNIQUEIDENTIFIER = CONVERT(UNIQUEIDENTIFIER, '25D5491C-42A8-4B04-B3AC-D648AF0F8032');
    DECLARE @AcceptedGuid    UNIQUEIDENTIFIER = CONVERT(UNIQUEIDENTIFIER, '21A29AEE-2D99-4DA3-8182-F31813B0C498');
    DECLARE @RejectedGuid    UNIQUEIDENTIFIER = CONVERT(UNIQUEIDENTIFIER, '0A6A71F7-B39F-4213-997E-2B3A13B6144C');
    DECLARE @DeclinedGuid    UNIQUEIDENTIFIER = CONVERT(UNIQUEIDENTIFIER, '708C00E6-F45F-4CB2-8E91-A80B8B8E802E');
    DECLARE @DeadGuid        UNIQUEIDENTIFIER = CONVERT(UNIQUEIDENTIFIER, '8C7F7526-559F-4CCF-8FC2-DB0DA67E793D');
	DECLARE @FirstChase      UNIQUEIDENTIFIER = CONVERT(UNIQUEIDENTIFIER, '9FF22CEA-A2A6-4907-9B2D-E62DF8150913');
	DECLARE @SecondChase     UNIQUEIDENTIFIER = CONVERT(UNIQUEIDENTIFIER, '1F01C16B-1A73-4844-A938-FE357405FD93');
    DECLARE @ExpiredGuid     UNIQUEIDENTIFIER = CONVERT(UNIQUEIDENTIFIER, 'E6FAC201-F98B-4B3A-AB55-83DC9F802D00'); -- CYB-461

    -------------------------------------------------------------------------
    -- Latest workflow status for THIS quote (single source of truth)
    -------------------------------------------------------------------------
    DECLARE @LatestStatusName NVARCHAR(250) = NULL;
    DECLARE @LatestStatusGuid UNIQUEIDENTIFIER = NULL;
    DECLARE @LatestRequiresUsersAction BIT = 0;
    DECLARE @LatestIsCustomerWaiting BIT = 0;

    SELECT TOP (1)
        @LatestStatusName           = wfs.Name,
        @LatestStatusGuid           = wfs.Guid,
        @LatestRequiresUsersAction  = ISNULL(wfs.RequiresUsersAction, 0),
        @LatestIsCustomerWaiting    = ISNULL(wfs.IsCustomerWaitingStatus, 0)
    FROM SCore.DataObjectTransition dot
    JOIN SCore.WorkflowStatus wfs ON wfs.ID = dot.StatusID
    WHERE dot.DataObjectGuid = @Guid
      AND dot.RowStatus NOT IN (0,254)
      AND wfs.RowStatus NOT IN (0,254)
    ORDER BY dot.DateTimeUTC DESC, dot.ID DESC;

    -------------------------------------------------------------------------
    -- STATUS datapill: ONLY latest status (no historical EXISTS)
    -- Prefer GUID matching; label text remains as today for UI consistency.
    -------------------------------------------------------------------------
    IF (@LatestStatusGuid IS NOT NULL)
    BEGIN
        IF (@LatestStatusGuid = @ReadyToSendGuid)
        BEGIN
            INSERT @DataPills (Label, Class, SortOrder)
            VALUES (N'Ready To Send', N'bg-warning', 1);
        END
		ELSE IF (@LatestStatusGuid = @FirstChase)
        BEGIN
            INSERT @DataPills (Label, Class, SortOrder)
            VALUES (N'1st Chase', N'bg-info', 1);
        END
		ELSE IF (@LatestStatusGuid = @SecondChase)
        BEGIN
            INSERT @DataPills (Label, Class, SortOrder)
            VALUES (N'2nd Chase', N'bg-info', 1);
        END
        ELSE IF (@LatestStatusGuid = @SentGuid)
        BEGIN
            INSERT @DataPills (Label, Class, SortOrder)
            VALUES (N'Sent', N'bg-info', 1);
        END
        ELSE IF (@LatestStatusGuid = @AcceptedGuid)
        BEGIN
            INSERT @DataPills (Label, Class, SortOrder)
            VALUES (N'Customer Accepted', N'bg-success', 1);
        END
        ELSE IF (@LatestStatusGuid IN (@RejectedGuid, @DeclinedGuid, @DeadGuid, @ExpiredGuid))
        BEGIN
            -- Keep the displayed label consistent with the actual latest name.
            -- (So if it’s “Declined”, label is “Declined”, etc.)
            INSERT @DataPills (Label, Class, SortOrder)
            VALUES (ISNULL(@LatestStatusName, N'Status'), N'bg-danger', 1);
        END
        -- else: deliberately no pill for every workflow status.
    END

    -------------------------------------------------------------------------
    -- Jobs pending creation (preserved)
    -------------------------------------------------------------------------
    IF (@DateAccepted IS NOT NULL)
    BEGIN
        DECLARE @JobCount INT;

        SELECT @JobCount = COUNT(1)
        FROM SSop.Quote_JobsSummary js
        WHERE js.QuoteGuid = @Guid;

        IF (@JobCount > 0)
        BEGIN
            INSERT @DataPills (Label, Class, SortOrder)
            VALUES (CONVERT(NVARCHAR(50), @JobCount) + N' job(s) pending creation.', N'bg-warning', 1);
        END
    END

    -------------------------------------------------------------------------
    -- Finance Account Credit Hold (preserved)
    -------------------------------------------------------------------------
    IF (EXISTS
    (
        SELECT 1
        FROM SSop.Quotes AS Q
        JOIN SSop.Quote_ExtendedInfo AS QE ON QE.ID = Q.ID
        JOIN SCrm.Accounts AC ON AC.ID = QE.FinanceAccountId
        WHERE Q.Guid = @Guid
          AND AC.AccountStatusID = 4
    ))
    BEGIN
        INSERT @DataPills (Label, Class, SortOrder)
        VALUES (N'Credit Hold', N'bg-danger', 1);
    END

    -------------------------------------------------------------------------
    -- Contract pills (preserved)
    -------------------------------------------------------------------------
    IF(@ContractGuid <> '00000000-0000-0000-0000-000000000000'
       OR @AgentContractGuid <> '00000000-0000-0000-0000-000000000000')
    BEGIN
        INSERT @DataPills (Label, Class, SortOrder)
        VALUES (N'Contract In Place', N'bg-warning', 2);

        DECLARE @EndDate DATE, @NextReviewDate DATE;

        IF(@ContractGuid <> '00000000-0000-0000-0000-000000000000')
        BEGIN
            SELECT @EndDate = EndDate, @NextReviewDate = NextReviewDate
            FROM SSop.Contracts
            WHERE Guid = @ContractGuid;
        END
        ELSE
        BEGIN
            SELECT @EndDate = EndDate, @NextReviewDate = NextReviewDate
            FROM SSop.Contracts
            WHERE Guid = @AgentContractGuid;
        END

        IF (@EndDate IS NOT NULL AND DATEDIFF(DAY, GETDATE(), @EndDate) <= 30)
        BEGIN
            INSERT @DataPills (Label, Class, SortOrder)
            VALUES (N'Contract Ending In ' + CONVERT(NVARCHAR(10), DATEDIFF(DAY, GETDATE(), @EndDate)) + N' Days', N'bg-danger', 8);
        END

        IF (@NextReviewDate IS NOT NULL AND DATEDIFF(DAY, GETDATE(), @NextReviewDate) <= 30)
        BEGIN
            INSERT @DataPills (Label, Class, SortOrder)
            VALUES (N'Contract Needs Reviewing By ' + CONVERT(NVARCHAR(10), @NextReviewDate, 23), N'bg-danger', 9);
        END
    END

    -------------------------------------------------------------------------
    -- Latest-only: User Action Required / Customer Waiting (preserved)
    -------------------------------------------------------------------------
    IF (@LatestRequiresUsersAction = 1)
    BEGIN
        INSERT @DataPills (Label, Class, SortOrder)
        VALUES (N'User Action Required', N'bg-warning', 0);
    END

    IF (@LatestIsCustomerWaiting = 1)
    BEGIN
        INSERT @DataPills (Label, Class, SortOrder)
        VALUES (N'Awaiting Customer', N'bg-warning', 0);
    END

    RETURN;
END
GO

GO

/* Deploy Function SSop.tvf_QuotesValidate using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Functions\SSop.tvf_QuotesValidate.sql */
/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R7C4 selected DEV schema source sync
    Object             : Function SSop.tvf_QuotesValidate
    Source schema hash : F9143B4EC0AE003EEC141260F1B0C69DB29A15195CBA1FC2568C035C1E1FE657
    Definition SHA-256 : 9066AB9BCF8EDB61EBD9D72D924446F5C94DD3130B44245067FBAF0ECD4F1ECF

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE OR ALTER FUNCTION [SSop].[tvf_QuotesValidate]
(
    @Guid UNIQUEIDENTIFIER,
    @DateSent DATE,
    @DeadDate DATE,
    @DateRejected DATE,
    @IsFinal BIT,
    @RevisionNumber INT,
    @OrganisationalUnitGuid UNIQUEIDENTIFIER,
    @DateDeclinedToQuote DATE,
    @DeclinedToQuoteReason NVARCHAR(MAX),
    @ContractGuid UNIQUEIDENTIFIER,
    @AgentContractGuid UNIQUEIDENTIFIER
)
RETURNS @ValidationResult TABLE
(
    ID INT IDENTITY(1, 1) NOT NULL,
    TargetGuid UNIQUEIDENTIFIER NOT NULL DEFAULT ('00000000-0000-0000-0000-000000000000'),
    TargetType CHAR(1) NOT NULL DEFAULT (''),
    IsReadOnly BIT NOT NULL DEFAULT ((0)),
    IsHidden BIT NOT NULL DEFAULT ((0)),
    IsInvalid BIT NOT NULL DEFAULT ((0)),
    IsInformationOnly BIT NOT NULL DEFAULT ((0)),
    Message NVARCHAR(2000) NOT NULL DEFAULT ('')
)
AS
BEGIN
    DECLARE @EntityTypeGuid UNIQUEIDENTIFIER = '1c4794c1-f956-4c32-b886-5500ac778a56';
    DECLARE @Final      BIT = 0;
    DECLARE @IsSent     BIT = 0;
    DECLARE @IsAccepted BIT = 0;
    DECLARE @IsRejected BIT = 0;
    DECLARE @IsDead     BIT = 0;
    DECLARE @IsReopened BIT = 0;
    DECLARE @ReadyForQuote UNIQUEIDENTIFIER = 'EB867FA0-9608-4CC7-93BE-CC8E8140E8F0';
    -- Ready to Send (replaces legacy IsFinal checkbox meaning)
    DECLARE @FinalStatus    UNIQUEIDENTIFIER = '02A2237F-2AE7-4E05-926F-38E8B7D050A0';
    -- Corrected GUIDs
    DECLARE @SentStatus     UNIQUEIDENTIFIER = '25D5491C-42A8-4B04-B3AC-D648AF0F8032';
    DECLARE @AcceptedStatus UNIQUEIDENTIFIER = '21A29AEE-2D99-4DA3-8182-F31813B0C498';
    DECLARE @RejectedStatus UNIQUEIDENTIFIER = '0A6A71F7-B39F-4213-997E-2B3A13B6144C';
    DECLARE @DeadStatus     UNIQUEIDENTIFIER = '8C7F7526-559F-4CCF-8FC2-DB0DA67E793D';
    -- CYB-461: saved by SSop.ExpireOverdueQuotesAndEnquiries
    DECLARE @ExpiredStatus  UNIQUEIDENTIFIER = 'E6FAC201-F98B-4B3A-AB55-83DC9F802D00';
    DECLARE @IsExpired  BIT = 0;
    DECLARE @Reopened UNIQUEIDENTIFIER;

    -- Make deterministic + rowstatus-safe (optional but recommended)
    SELECT TOP (1) @Reopened = Guid
    FROM SCore.WorkflowStatus
    WHERE RowStatus NOT IN (0,254)
      AND Name LIKE N'%Reopened%'
    ORDER BY ID;
    -------------------------------------------------------------------------
    -- Determine flags based on the LATEST workflow transition for this Quote (latest-only)
    -------------------------------------------------------------------------
DECLARE
      @LatestWorkflowStatusGuid UNIQUEIDENTIFIER = NULL
    , @LatestIsActiveStatus     BIT              = NULL
    , @LatestIsCompleteStatus   BIT              = NULL;
 
	;WITH LatestEffective AS
	(
		SELECT TOP (1)
			  wfs.Guid             AS LatestWorkflowStatusGuid
			, wfs.IsActiveStatus   AS LatestIsActiveStatus
			, wfs.IsCompleteStatus AS LatestIsCompleteStatus
		FROM SCore.DataObjectTransition dot
		JOIN SCore.WorkflowStatus wfs ON wfs.ID = dot.StatusID
		WHERE dot.RowStatus NOT IN (0,254)
		  AND wfs.RowStatus NOT IN (0,254)
		  AND dot.DataObjectGuid = @Guid
		ORDER BY
			dot.ID DESC
	)
	SELECT
		  @LatestWorkflowStatusGuid = LatestWorkflowStatusGuid
		, @LatestIsActiveStatus     = LatestIsActiveStatus
		, @LatestIsCompleteStatus   = LatestIsCompleteStatus
	FROM LatestEffective;

    -- Latest-only flags
    SET @Final      = CASE WHEN @LatestWorkflowStatusGuid = @FinalStatus    THEN 1 ELSE 0 END;
    SET @IsSent     = CASE WHEN @LatestWorkflowStatusGuid = @SentStatus     THEN 1 ELSE 0 END;
    SET @IsAccepted = CASE WHEN @LatestWorkflowStatusGuid = @AcceptedStatus THEN 1 ELSE 0 END;
    SET @IsRejected = CASE WHEN @LatestWorkflowStatusGuid = @RejectedStatus THEN 1 ELSE 0 END;
    SET @IsDead     = CASE WHEN @LatestWorkflowStatusGuid = @DeadStatus     THEN 1 ELSE 0 END;
    SET @IsExpired  = CASE WHEN @LatestWorkflowStatusGuid = @ExpiredStatus  THEN 1 ELSE 0 END;
    SET @IsReopened = CASE WHEN @LatestWorkflowStatusGuid = @Reopened       THEN 1 ELSE 0 END;
    -------------------------------------------------------------------------
    -- Prevent changing Quote if Enquiry not ready for quote review
    -------------------------------------------------------------------------

	/*
		Additional check for reopened status. 

		=======================================================================================
		= SET @IsReopened = CASE WHEN @LatestWorkflowStatusGuid = @Reopenen THEN 1 ELSE 0 END =
		=======================================================================================

		The above is based on the last available status. Currently, if we reopen a quote,
		it first assigns "Reopened" and then immediately after that "Quoting". Aka, it would fail.


	*/
	IF(@IsReopened = 0)
	BEGIN

		IF(EXISTS
				(
					SELECT 1  
					FROM SCore.DataObjectTransition AS Dob
					JOIN SCore.WorkflowStatus AS wfs ON (Dob.StatusID = wfs.ID)
					WHERE 
								(Dob.RowStatus NOT IN (0, 254))
							AND (wfs.RowStatus NOT IN (0,254))
							AND (Dob.DataObjectGuid = @Guid)
							AND (
										wfs.Guid = '9A60F983-24BA-4733-907E-C5CCE0B691CB' --Quoting
									OR  wfs.Guid = '34EF363A-C8F7-4BA8-A2C6-067EBAEF12FD' --Reopened
								)
							AND (
										dob.Comment LIKE N'%Reopened quote returned to quoting.%'
									OR  dob.Comment LIKE N'%System Imported%'
								)
							AND NOT EXISTS
								(
									SELECT 1  
									FROM SCore.DataObjectTransition AS Dob2
									JOIN SCore.WorkflowStatus AS wfs2 ON (Dob2.StatusID = wfs2.ID)
									WHERE 
											(Dob2.RowStatus NOT IN (0, 254))
										AND (wfs2.RowStatus NOT IN (0, 254))
										AND (Dob2.DataObjectGuid = @Guid )
										AND (Dob2.ID > Dob.ID)
								)
				)
		  )

		  SET @IsReopened = 1

	 END;

    -------------------------------------------------------------------------
    -- CYB-462
    -- Quote Superusers (same QUOTESU group SSop.QuoteReopen checks) can keep
    -- editing a quote after it has been sent.
    -------------------------------------------------------------------------
    DECLARE @UserID INT = ISNULL(CONVERT(INT, SESSION_CONTEXT(N'user_id')), -1);
    DECLARE @IsQuoteSuperUser BIT = 0;

    IF EXISTS
    (
        SELECT 1
        FROM SCore.UserGroups AS ug
        JOIN SCore.Groups AS g
            ON g.ID = ug.GroupID
        WHERE ug.IdentityID = @UserID
          AND g.Code = N'QUOTESU'
          AND ug.RowStatus NOT IN (0,254)
          AND g.RowStatus NOT IN (0,254)
    )
    BEGIN
        SET @IsQuoteSuperUser = 1;
    END;

    -------------------------------------------------------------------------
    -- CYB-462
    -- A quote counts as sent once a Sent transition exists after its latest
    -- Reopened transition. The Sent status stays in force through the later
    -- statuses (1st/2nd Chase, Accepted...). QuoteReopen does not clear
    -- DateSent, so DateSent alone only counts for quotes never reopened
    -- (legacy rows without workflow history).
    -- A 1st/2nd Chase or Customer Accepted transition also counts as sent:
    -- legacy accepted quotes have an Accepted status but no Sent status and
    -- often no DateSent.
    -------------------------------------------------------------------------
    DECLARE @LastReopenedTransitionID INT = NULL;
    DECLARE @HasBeenSent BIT = 0;

    SELECT @LastReopenedTransitionID = MAX(dot.ID)
    FROM SCore.DataObjectTransition AS dot
    JOIN SCore.WorkflowStatus AS wfs
        ON wfs.ID = dot.StatusID
    WHERE dot.DataObjectGuid = @Guid
      AND dot.RowStatus NOT IN (0,254)
      AND wfs.RowStatus NOT IN (0,254)
      AND wfs.Guid = @Reopened;

    IF EXISTS
    (
        SELECT 1
        FROM SCore.DataObjectTransition AS dot
        JOIN SCore.WorkflowStatus AS wfs
            ON wfs.ID = dot.StatusID
        WHERE dot.DataObjectGuid = @Guid
          AND dot.RowStatus NOT IN (0,254)
          AND wfs.RowStatus NOT IN (0,254)
          AND wfs.Guid IN
              (
                  @SentStatus,
                  '9FF22CEA-A2A6-4907-9B2D-E62DF8150913', -- 1st Chase
                  '1F01C16B-1A73-4844-A938-FE357405FD93', -- 2nd Chase
                  @AcceptedStatus
              )
          AND dot.ID > ISNULL(@LastReopenedTransitionID, 0)
    )
    OR (@DateSent IS NOT NULL AND @LastReopenedTransitionID IS NULL)
    BEGIN
        SET @HasBeenSent = 1;
    END;

	 /*
		CYB-321: 
		Only enable the below fields if the quote has been revised.
	 */
	 IF(@RevisionNumber < 1)
	 BEGIN
		INSERT @ValidationResult
        (
            TargetGuid,
            TargetType,
            IsReadOnly,
            IsHidden,
            IsInvalid,
            Message
        )
        SELECT
            epfvv.Guid,
            N'P',
            1,
            0,
            0,
            N''
        FROM SCore.EntityPropertiesForValidationV AS epfvv
        WHERE epfvv.[Schema] = N'SSop'
          AND epfvv.Hobt IN (N'Quotes')
		  AND epfvv.Name IN (
				N'ClientAccountId', 
				N'ClientAddressId', 
				N'ClientContactId', 
				N'AgentAccountId', 
				N'AgentAddressId', 
				N'AgentContactId',
				N'PropertyId',
				N'JobTypeGuid'
				
		  );
		

	 END;



    -------------------------------------------------------------------------
    -- CYB-317
    -- Lock superseded quote revisions.
    -- Only the latest active revision in a quote chain remains editable.
    -------------------------------------------------------------------------
    IF EXISTS
    (
        SELECT 1
        FROM SSop.Quotes AS qCurrent
        JOIN SSop.Quotes AS qOther
            ON qOther.RowStatus NOT IN (0,254)
           AND qOther.Number = qCurrent.Number
           AND ISNULL(qOther.OriginalQuoteId, -1) =
               CASE
                   WHEN qCurrent.OriginalQuoteId = -1 THEN qCurrent.ID
                   ELSE qCurrent.OriginalQuoteId
               END
           AND qOther.RevisionNumber > qCurrent.RevisionNumber
        WHERE qCurrent.Guid = @Guid
          AND qCurrent.RowStatus NOT IN (0,254)
    )
    BEGIN
        INSERT @ValidationResult
        (
            TargetGuid,
            TargetType,
            IsReadOnly,
            IsHidden,
            IsInvalid,
            Message
        )
        SELECT
            epfvv.Guid,
            N'P',
            1,
            0,
            0,
            N''
        FROM SCore.EntityPropertiesForValidationV AS epfvv
        WHERE epfvv.[Schema] = N'SSop'
          AND epfvv.Hobt IN (N'Quotes', N'Quote_ExtendedInfo');

        RETURN;
    END;

    -------------------------------------------------------------------------
    -- Lock quote when jobs exist or dead
    -------------------------------------------------------------------------
    IF EXISTS
    (
        SELECT 1
        FROM SSop.QuoteItems qi
        JOIN SSop.Quotes q ON q.ID = qi.QuoteId
        WHERE q.Guid = @Guid
          AND qi.RowStatus NOT IN (0,254)
          AND qi.CreatedJobId > 0
		  AND @IsReopened = 0
		  
    ) 
    OR ((@IsDead = 1 OR @DeadDate IS NOT NULL) AND @IsReopened = 0)
    BEGIN
        INSERT @ValidationResult (TargetGuid, TargetType, IsReadOnly, IsHidden, IsInvalid, Message)
        VALUES (@EntityTypeGuid, N'E', 1, 0, 0, N'');
        RETURN;
    END;

    -------------------------------------------------------------------------
    -- CDM FeeCap hide
    -------------------------------------------------------------------------
	IF(@IsReopened = 0)
	BEGIN
		IF EXISTS
		(
			SELECT 1
			FROM SCore.OrganisationalUnits ou
			WHERE ou.Guid = @OrganisationalUnitGuid
			  AND ou.Name LIKE N'CDM%'
			  AND ou.RowStatus NOT IN (0,254)
		)
		BEGIN
			INSERT @ValidationResult (TargetGuid, TargetType, IsReadOnly, IsHidden, IsInvalid, Message)
			SELECT epfvv.Guid, N'P', 0, 1, 0, N''
			FROM SCore.EntityPropertiesForValidationV epfvv
			WHERE epfvv.[Schema] = N'SSop'
			  AND epfvv.Hobt = N'Quotes'
			  AND epfvv.Name = N'FeeCap';
		END;
	END;
    -------------------------------------------------------------------------
    -- RevisionNumber rule
    -------------------------------------------------------------------------
    IF (@RevisionNumber < 1)
    BEGIN
        INSERT @ValidationResult (TargetGuid, TargetType, IsReadOnly, IsHidden, IsInvalid, Message)
        SELECT epfvv.Guid, N'P', 1, 1, 0, N''
        FROM SCore.EntityPropertiesForValidationV epfvv
        WHERE epfvv.[Schema] = N'SSop'
          AND epfvv.Hobt = N'Quotes'
          AND epfvv.Name = N'RevisionNumber';
    END;
    -------------------------------------------------------------------------
    -- Don’t allow progress beyond Send until quote is Sent
    -- CYB-462: uses @HasBeenSent, not the latest status alone, so the
    -- status-change fields stay open at 1st/2nd Chase and Customer Accepted
    -- when DateSent was never filled in.
    -------------------------------------------------------------------------
    IF (@HasBeenSent = 0)
    BEGIN
        INSERT @ValidationResult (TargetGuid, TargetType, IsReadOnly, IsHidden, IsInvalid, Message)
        SELECT epfvv.Guid, N'P', 1, 1, 0, N''
        FROM SCore.EntityPropertiesForValidationV epfvv
        WHERE epfvv.[Schema] = N'SSop'
          AND epfvv.Hobt = N'Quotes'
          AND epfvv.Name IN (N'DateAccepted', N'DateRejected', N'RejectionReason', N'ChaseDate1', N'ChaseDate2');
    END;
    -------------------------------------------------------------------------
    -- Sent => IsFinal locked (legacy field still locked, but NO net error now)
    ---------------------------------------------------------------------------
    IF ((@IsSent = 1) OR (@DateSent IS NOT NULL))
    BEGIN
        INSERT @ValidationResult (TargetGuid, TargetType, IsReadOnly, IsHidden, IsInvalid, Message)
        SELECT epfvv.Guid, N'P', 1, 0, 0, N''
        FROM SCore.EntityPropertiesForValidationV epfvv
        WHERE epfvv.[Schema] = N'SSop'
          AND epfvv.Hobt = N'Quotes'
          AND epfvv.Name = N'IsFinal';
    END;
    -------------------------------------------------------------------------
    -- Block DateSent until workflow status is Ready to Send
    -------------------------------------------------------------------------
    IF (@Final = 0)
    BEGIN
        INSERT @ValidationResult (TargetGuid, TargetType, IsReadOnly, IsHidden, IsInvalid, Message)
        SELECT epfvv.Guid, N'P', 1, 1, 0, N''
        FROM SCore.EntityPropertiesForValidationV epfvv
        WHERE epfvv.[Schema] = N'SSop'
          AND epfvv.Hobt = N'Quotes'
          AND epfvv.Name = N'DateSent';
    END;
    -------------------------------------------------------------------------
    -- Rejected locking (latest-only + reopen exception)
    -------------------------------------------------------------------------
    IF (((@IsRejected = 1) OR (@DateRejected IS NOT NULL)) AND @IsReopened = 0)
    BEGIN
        INSERT @ValidationResult (TargetGuid, TargetType, IsReadOnly, IsHidden, IsInvalid, Message)
        SELECT epfvv.Guid, N'P', 1, 0, 0, N''
        FROM SCore.EntityPropertiesForValidationV epfvv
        WHERE epfvv.[Schema] = N'SSop'
          AND epfvv.Hobt = N'Quotes';
    END;
    -------------------------------------------------------------------------
    -- Hide AgentContractID if ContractID set, and vice versa
    -------------------------------------------------------------------------
    IF (@ContractGuid <> '00000000-0000-0000-0000-000000000000')
    BEGIN
        INSERT @ValidationResult (TargetGuid, TargetType, IsReadOnly, IsHidden, IsInvalid, Message)
        SELECT epfvv.Guid, N'P', 0, 1, 0, N''
        FROM SCore.EntityPropertiesForValidationV epfvv
        WHERE epfvv.[Schema] = N'SSop'
          AND epfvv.Hobt = N'Quotes'
          AND epfvv.Name = N'AgentContractID';
    END
    ELSE IF (@AgentContractGuid <> '00000000-0000-0000-0000-000000000000')
    BEGIN
        INSERT @ValidationResult (TargetGuid, TargetType, IsReadOnly, IsHidden, IsInvalid, Message)
        SELECT epfvv.Guid, N'P', 0, 1, 0, N''
        FROM SCore.EntityPropertiesForValidationV epfvv
        WHERE epfvv.[Schema] = N'SSop'
          AND epfvv.Hobt = N'Quotes'
          AND epfvv.Name = N'ContractID';
    END;
    -------------------------------------------------------------------------
    -- Final/Ready-to-Send lockdown of fields (KEEP) but NO net value error here
    -- CYB-462: ExpiryDate stays editable until the quote is Sent.
    -------------------------------------------------------------------------
    IF (@Final = 1)
       AND NOT EXISTS
       (
           SELECT 1
           FROM SSop.Quotes q
           WHERE q.Guid = @Guid
             AND q.LegacyId IS NOT NULL
             AND
             (
                 q.OrganisationalUnitID  < 0
              OR q.QuotingUserId         < 0
              OR q.QuotingConsultantId   < 0
             )
       )
    BEGIN
        INSERT @ValidationResult (TargetGuid, TargetType, IsReadOnly, IsHidden, IsInvalid, Message)
        SELECT epfvv.Guid, N'P', 1, 0, 0, N''
        FROM SCore.EntityPropertiesForValidationV epfvv
        WHERE epfvv.[Schema] = N'SSop'
          AND epfvv.Hobt = N'Quotes'
          AND epfvv.Name NOT IN
          (
              N'ChaseDate2', N'ChaseDate1', N'RejectionReason', N'DateRejected', N'DateAccepted',
              N'IsFinal', N'DateSent', N'ExpiryDate'
          );
        INSERT @ValidationResult (TargetGuid, TargetType, IsReadOnly, IsHidden, IsInvalid, Message)
        SELECT epfvv.Guid, N'P', 1, 0, 0, N''
        FROM SCore.EntityPropertiesForValidationV epfvv
        WHERE epfvv.[Schema] = N'SSop'
          AND epfvv.Hobt = N'Quote_ExtendedInfo';
    END;
    -------------------------------------------------------------------------
    -- CYB-462
    -- Sent lockdown: once sent, every quote field (ExpiryDate included) and
    -- Quote_ExtendedInfo locks permanently. General users can only record
    -- status changes (chase, accepted, rejected). Quote Superusers are exempt.
    -------------------------------------------------------------------------
    IF (@HasBeenSent = 1 AND @IsQuoteSuperUser = 0 AND @IsReopened = 0)
    BEGIN
        INSERT @ValidationResult (TargetGuid, TargetType, IsReadOnly, IsHidden, IsInvalid, Message)
        SELECT epfvv.Guid, N'P', 1, 0, 0, N''
        FROM SCore.EntityPropertiesForValidationV epfvv
        WHERE epfvv.[Schema] = N'SSop'
          AND epfvv.Hobt = N'Quotes'
          AND epfvv.Name NOT IN
          (
              N'ChaseDate2', N'ChaseDate1', N'RejectionReason', N'DateRejected', N'DateAccepted'
          );
        INSERT @ValidationResult (TargetGuid, TargetType, IsReadOnly, IsHidden, IsInvalid, Message)
        SELECT epfvv.Guid, N'P', 1, 0, 0, N''
        FROM SCore.EntityPropertiesForValidationV epfvv
        WHERE epfvv.[Schema] = N'SSop'
          AND epfvv.Hobt = N'Quote_ExtendedInfo';
    END;
    -------------------------------------------------------------------------
    -- CYB-461
    -- Expired lockdown: an expired quote is fully read-only (every Quotes
    -- and Quote_ExtendedInfo field) for general users, whatever status it
    -- expired from. Quote Superusers are exempt.
    -------------------------------------------------------------------------
    IF (@IsExpired = 1 AND @IsQuoteSuperUser = 0 AND @IsReopened = 0)
    BEGIN
        INSERT @ValidationResult (TargetGuid, TargetType, IsReadOnly, IsHidden, IsInvalid, Message)
        SELECT epfvv.Guid, N'P', 1, 0, 0, N''
        FROM SCore.EntityPropertiesForValidationV epfvv
        WHERE epfvv.[Schema] = N'SSop'
          AND epfvv.Hobt IN (N'Quotes', N'Quote_ExtendedInfo');
    END;
    -------------------------------------------------------------------------
    -- Complete-status lock (latest-only)
    -------------------------------------------------------------------------
    IF (@LatestIsCompleteStatus = 1 AND @IsReopened = 0 )
    BEGIN
        INSERT @ValidationResult (TargetGuid, TargetType, IsReadOnly, IsHidden, IsInvalid, Message)
        SELECT epfvv.Guid, N'P', 1, 0, 0, N''
        FROM SCore.EntityPropertiesForValidationV epfvv
        WHERE epfvv.[Schema] = N'SSop'
          AND epfvv.Hobt     = N'Quotes';
    END;
    RETURN;
END;
GO

