/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R7C4 selected DEV schema source sync
    Object             : StoredProcedure SFin.InvoiceRequestUpsert
    Source schema hash : DA8A6C333967DE83EEA57BA45B4070F3BFF7C19FD6334A327F862842C4B8E9FE
    Definition SHA-256 : 9980BDC9ADE923CEA1AB2749E477D6F1C98048A728D4889D7CCA115A8F983997

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE OR ALTER PROCEDURE [SFin].[InvoiceRequestUpsert]
(
    @JobGuid UNIQUEIDENTIFIER,
    @RequesterUserGuid UNIQUEIDENTIFIER,
    @Notes NVARCHAR(MAX),
    @Guid UNIQUEIDENTIFIER,
    @InvoicingType NVARCHAR(10),
    @ExpectedDate DATE,
    @ManualStatus BIT,
    @PaymentStatusGuid UNIQUEIDENTIFIER,
	@FinanceAccountGuid UNIQUEIDENTIFIER,
	@IsWIP BIT,
	@WIPReason NVARCHAR(MAX)
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @JobID INT,
            @RequesterUserId INT,
            @PaymentStatusID BIGINT,
            @DataObjectWasInserted BIT;

    -- Null-safety for NOT NULL column
    SET @Notes = ISNULL(@Notes, N'');

    -- Resolve Job
    SELECT @JobID = ID
    FROM SJob.Jobs
    WHERE [Guid] = @JobGuid;

    IF (@JobID IS NULL)
        THROW 60000, N'InvoiceRequestUpsert: JobGuid not found.', 1;

    -- Resolve Requester
    SELECT @RequesterUserId = ID
    FROM SCore.Identities
    WHERE [Guid] = @RequesterUserGuid;

    IF (@RequesterUserId IS NULL)
        THROW 60000, N'InvoiceRequestUpsert: RequesterUserGuid not found.', 1;

    -- Resolve Payment Status
    SELECT @PaymentStatusID = ID
    FROM SFin.InvoicePaymentStatus
    WHERE [Guid] = @PaymentStatusGuid;

    IF (@PaymentStatusID IS NULL)
        THROW 60000, N'InvoiceRequestUpsert: PaymentStatusGuid not found.', 1;

    -- Ensure DataObject exists (always do this)
    EXEC SCore.UpsertDataObject
        @Guid = @Guid,
        @SchemeName = N'SFin',
        @ObjectName = N'InvoiceRequests',
        @IncludeDefaultSecurity = 0,
        @IsInsert = @DataObjectWasInserted OUTPUT;

    -- IMPORTANT: Decide insert/update based on SFin.InvoiceRequests, NOT DataObjects
    IF NOT EXISTS (SELECT 1 FROM SFin.InvoiceRequests WITH (UPDLOCK, HOLDLOCK) WHERE [Guid] = @Guid)
    BEGIN
        INSERT SFin.InvoiceRequests
        (
            RowStatus,
            Guid,
            Notes,
            RequesterUserId,
            CreatedDateTimeUTC,
            JobId,
            InvoicingType,
            ExpectedDate,
            ManualStatus,
            InvoicePaymentStatusID,
			isWIP,
			WIPReason
        )
        VALUES
        (
            1,
            @Guid,
            @Notes,
            @RequesterUserId,
            GETUTCDATE(),
            @JobID,
            ISNULL(@InvoicingType, N''),
            @ExpectedDate,
            ISNULL(@ManualStatus, 0),
            @PaymentStatusID,
			@IsWIP,
			@WIPReason
        );
    END
    ELSE
    BEGIN
        UPDATE ir
        SET
            ir.Notes = @Notes,
            ir.JobId = @JobID,
            ir.InvoicingType = ISNULL(@InvoicingType, N''),
            ir.ExpectedDate = @ExpectedDate,
            ir.ManualStatus = ISNULL(@ManualStatus, 0),
            ir.InvoicePaymentStatusID = @PaymentStatusID,
			ir.RequesterUserId = @RequesterUserId,
			ir.FinanceAccountGuid = @FinanceAccountGuid,
			ir.isWIP = @IsWIP,
			ir.WIPReason = @WIPReason
        FROM SFin.InvoiceRequests ir
        WHERE ir.[Guid] = @Guid;
    END
END
GO

