SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/* =============================================================================
   CYB-461 - Enquiry and Quote auto-expiry
   Object: SSop.ExpireOverdueQuotesAndEnquiries

   Records a saved "Expired" workflow status for every Quote and Enquiry that
   the calculated-status views already show as expired:
   - Quotes:    SSop.Quote_CalculatedFields.QuoteStatus = 'Expired'
                (Quoting / Ready to Send / Sent / 1st Chase / 2nd Chase past
                ExpiryDate, or a legacy quote with no history past ExpiryDate).
   - Enquiries: SSop.Enquiry_CalculatedFields.EnquiryStatus IN
                ('Expired', 'Quote Expired') (no quotes and the quoting deadline
                passed more than 2 days ago, or every quote expired).

   The views stay the single definition of the expiry rules; this procedure
   only persists them. Every status is written through
   SCore.DataObjectTransitionUpsert, never directly.

   Idempotent and retry-safe: a record whose latest saved status is already
   "Expired" is skipped, and an application lock stops concurrent runs (the
   API runs this from a hosted worker on more than one replica).

   Notifications: a record that expired more than @NotifyWithinDays ago is
   expired silently (notification triggers suppressed through session
   context), so the first run clears the historic backlog without sending a
   notification per record. Recently expired records notify normally.

   Result sets:
   1) one summary row: LockAcquired, QuotesExpired, EnquiriesExpired,
      ExpiredSilently, Failed
   2) one row per failed record: RecordType, RecordGuid, ErrorMessage
============================================================================= */
CREATE OR ALTER PROCEDURE [SSop].[ExpireOverdueQuotesAndEnquiries]
(
    @ServiceUserGuid UNIQUEIDENTIFIER,
    @MaxRecords INT = 500,
    @NotifyWithinDays INT = 7
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @ExpiredStatusGuid UNIQUEIDENTIFIER = 'E6FAC201-F98B-4B3A-AB55-83DC9F802D00';
    DECLARE @EmptyGuid UNIQUEIDENTIFIER = '00000000-0000-0000-0000-000000000000';
    DECLARE @LockName NVARCHAR(255) = N'SSop.ExpireOverdueQuotesAndEnquiries';

    IF NOT EXISTS
    (
        SELECT 1
        FROM SCore.WorkflowStatus ws
        WHERE ws.Guid = @ExpiredStatusGuid
          AND ws.RowStatus NOT IN (0,254)
          AND ws.ShowInQuotes = 1
          AND ws.ShowInEnquiries = 1
    )
        THROW 62001, N'ExpireOverdueQuotesAndEnquiries: the "Expired" WorkflowStatus (E6FAC201-F98B-4B3A-AB55-83DC9F802D00) is missing, inactive, or not enabled for Quotes and Enquiries.', 1;

    IF NOT EXISTS
    (
        SELECT 1
        FROM SCore.Identities i
        WHERE i.Guid = @ServiceUserGuid
          AND i.RowStatus NOT IN (0,254)
    )
        THROW 62002, N'ExpireOverdueQuotesAndEnquiries: @ServiceUserGuid does not match an active SCore.Identities row.', 1;

    IF (@MaxRecords IS NULL OR @MaxRecords <= 0)
        SET @MaxRecords = 500;

    IF (@NotifyWithinDays IS NULL OR @NotifyWithinDays < 0)
        SET @NotifyWithinDays = 0;

    DECLARE @LockResult INT;

    EXEC @LockResult = sys.sp_getapplock
        @Resource    = @LockName,
        @LockMode    = N'Exclusive',
        @LockOwner   = N'Session',
        @LockTimeout = 0;

    IF (@LockResult < 0)
    BEGIN
        SELECT
            LockAcquired     = CONVERT(bit, 0),
            QuotesExpired    = 0,
            EnquiriesExpired = 0,
            ExpiredSilently  = 0,
            Failed           = 0;

        SELECT
            RecordType   = CONVERT(nvarchar(10), NULL),
            RecordGuid   = CONVERT(uniqueidentifier, NULL),
            ErrorMessage = CONVERT(nvarchar(4000), NULL)
        WHERE 1 = 0;

        RETURN;
    END

    DECLARE @TodayUtc DATE = CONVERT(date, SYSUTCDATETIME());
    DECLARE @NotifyFrom DATE = DATEADD(DAY, -@NotifyWithinDays, @TodayUtc);

    DECLARE @PreviousDisableTriggers SQL_VARIANT = SESSION_CONTEXT(N'S_disable_triggers');
    DECLARE @PreviousDisableNotificationTriggers SQL_VARIANT = SESSION_CONTEXT(N'S_disable_notification_triggers');

    DECLARE @QuotesExpired INT = 0;
    DECLARE @EnquiriesExpired INT = 0;
    DECLARE @ExpiredSilently INT = 0;

    DECLARE @Work TABLE
    (
        Seq           INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
        RecordType    NVARCHAR(10)      NOT NULL,
        RecordGuid    UNIQUEIDENTIFIER  NOT NULL,
        OldStatusGuid UNIQUEIDENTIFIER  NULL,
        ExpiredOn     DATE              NULL
    );

    DECLARE @Failures TABLE
    (
        RecordType   NVARCHAR(10)     NOT NULL,
        RecordGuid   UNIQUEIDENTIFIER NOT NULL,
        ErrorMessage NVARCHAR(4000)   NOT NULL
    );

    BEGIN TRY
        DECLARE @Phase INT = 1;

        WHILE (@Phase <= 2)
        BEGIN
            DELETE FROM @Work;

            DECLARE @Remaining INT = @MaxRecords - @QuotesExpired - @EnquiriesExpired
                                     - (SELECT COUNT(1) FROM @Failures);

            IF (@Remaining <= 0)
                BREAK;

            IF (@Phase = 1)
            BEGIN
                -- Quotes. Latest status uses ORDER BY ID DESC, matching
                -- SSop.Quote_CalculatedFields. Both expiry branches of the
                -- view need ExpiryDate < today, so that pre-filters the view.
                INSERT INTO @Work (RecordType, RecordGuid, OldStatusGuid, ExpiredOn)
                SELECT TOP (@Remaining)
                    N'Quote',
                    q.Guid,
                    LatestStatus.Guid,
                    q.ExpiryDate
                FROM SSop.Quotes AS q
                JOIN SSop.Quote_CalculatedFields AS qcf ON qcf.ID = q.ID
                OUTER APPLY
                (
                    SELECT TOP (1) wfs.Guid
                    FROM SCore.DataObjectTransition AS dot
                    JOIN SCore.WorkflowStatus AS wfs ON wfs.ID = dot.StatusID
                    WHERE dot.DataObjectGuid = q.Guid
                      AND dot.RowStatus NOT IN (0,254)
                      AND wfs.RowStatus NOT IN (0,254)
                    ORDER BY dot.ID DESC
                ) AS LatestStatus
                WHERE q.RowStatus NOT IN (0,254)
                  AND q.ID > 0
                  AND q.ExpiryDate < @TodayUtc
                  AND qcf.QuoteStatus = N'Expired'
                  AND ISNULL(LatestStatus.Guid, @EmptyGuid) <> @ExpiredStatusGuid
                ORDER BY q.ExpiryDate, q.ID;
            END
            ELSE
            BEGIN
                -- Enquiries, selected after the quotes so quote expiry that
                -- already synced to the enquiry is not written twice. Latest
                -- status matches SSop.Enquiry_CalculatedFields.
                INSERT INTO @Work (RecordType, RecordGuid, OldStatusGuid, ExpiredOn)
                SELECT TOP (@Remaining)
                    N'Enquiry',
                    e.Guid,
                    LatestStatus.Guid,
                    ISNULL(QuoteAgg.LatestExpiryDate, DATEADD(DAY, 2, e.QuotingDeadlineDate))
                FROM SSop.Enquiries AS e
                OUTER APPLY
                (
                    SELECT LatestExpiryDate = MAX(q.ExpiryDate)
                    FROM SSop.EnquiryServices AS es
                    JOIN SSop.Quotes AS q ON q.EnquiryServiceID = es.ID
                    WHERE es.EnquiryId = e.ID
                      AND es.RowStatus NOT IN (0,254)
                      AND q.RowStatus NOT IN (0,254)
                ) AS QuoteAgg
                JOIN SSop.Enquiry_CalculatedFields AS ecf ON ecf.ID = e.ID
                OUTER APPLY
                (
                    SELECT TOP (1) wfs.Guid
                    FROM SCore.DataObjectTransition AS dot
                    JOIN SCore.WorkflowStatus AS wfs ON wfs.ID = dot.StatusID
                    WHERE dot.DataObjectGuid = e.Guid
                      AND dot.RowStatus NOT IN (0,254)
                      AND wfs.RowStatus NOT IN (0,254)
                      AND ISNULL(wfs.ShowInEnquiries, 0) = 1
                    ORDER BY dot.DateTimeUTC DESC, dot.ID DESC
                ) AS LatestStatus
                WHERE e.RowStatus NOT IN (0,254)
                  AND e.ID > 0
                  AND
                  (
                      QuoteAgg.LatestExpiryDate < @TodayUtc
                      OR (QuoteAgg.LatestExpiryDate IS NULL AND e.QuotingDeadlineDate < DATEADD(DAY, -2, @TodayUtc))
                  )
                  AND ecf.EnquiryStatus IN (N'Expired', N'Quote Expired')
                  AND ISNULL(LatestStatus.Guid, @EmptyGuid) <> @ExpiredStatusGuid
                ORDER BY ISNULL(QuoteAgg.LatestExpiryDate, DATEADD(DAY, 2, e.QuotingDeadlineDate)), e.ID;
            END

            DECLARE @Seq INT = 0;

            WHILE (1 = 1)
            BEGIN
                DECLARE @RecordType NVARCHAR(10) = NULL;
                DECLARE @RecordGuid UNIQUEIDENTIFIER = NULL;
                DECLARE @OldStatusGuid UNIQUEIDENTIFIER = NULL;
                DECLARE @ExpiredOn DATE = NULL;

                SELECT TOP (1)
                    @Seq           = w.Seq,
                    @RecordType    = w.RecordType,
                    @RecordGuid    = w.RecordGuid,
                    @OldStatusGuid = w.OldStatusGuid,
                    @ExpiredOn     = w.ExpiredOn
                FROM @Work AS w
                WHERE w.Seq > @Seq
                ORDER BY w.Seq;

                IF (@RecordGuid IS NULL)
                    BREAK;

                DECLARE @Silent BIT = CASE WHEN @ExpiredOn < @NotifyFrom THEN 1 ELSE 0 END;
                DECLARE @TransitionGuid UNIQUEIDENTIFIER = NEWID();
                DECLARE @Comment NVARCHAR(MAX) =
                    CASE @RecordType
                        WHEN N'Quote' THEN N'Automatically expired: the quote expiry date has passed.'
                        ELSE N'Automatically expired: all quotes have expired or the quoting deadline has passed.'
                    END;

                IF (@Silent = 1)
                BEGIN
                    EXEC sys.sp_set_session_context @key = N'S_disable_triggers', @value = 1, @read_only = 0;
                    EXEC sys.sp_set_session_context @key = N'S_disable_notification_triggers', @value = 1, @read_only = 0;
                END

                BEGIN TRY
                    EXEC SCore.DataObjectTransitionUpsert
                        @Guid              = @TransitionGuid,
                        @OldStatusGuid     = @OldStatusGuid,
                        @StatusGuid        = @ExpiredStatusGuid,
                        @Comment           = @Comment,
                        @CreatedByUserGuid = @ServiceUserGuid,
                        @SurveyorUserGuid  = NULL,
                        @DataObjectGuid    = @RecordGuid,
                        @IsImported        = 0;

                    IF (@RecordType = N'Quote')
                        SET @QuotesExpired += 1;
                    ELSE
                        SET @EnquiriesExpired += 1;

                    IF (@Silent = 1)
                        SET @ExpiredSilently += 1;
                END TRY
                BEGIN CATCH
                    -- A caller-owned transaction that is now doomed cannot
                    -- continue; stop and surface the error.
                    IF (XACT_STATE() = -1)
                        THROW;

                    INSERT INTO @Failures (RecordType, RecordGuid, ErrorMessage)
                    VALUES (@RecordType, @RecordGuid, LEFT(ERROR_MESSAGE(), 4000));
                END CATCH

                IF (@Silent = 1)
                BEGIN
                    EXEC sys.sp_set_session_context @key = N'S_disable_triggers', @value = @PreviousDisableTriggers, @read_only = 0;
                    EXEC sys.sp_set_session_context @key = N'S_disable_notification_triggers', @value = @PreviousDisableNotificationTriggers, @read_only = 0;
                END
            END

            SET @Phase += 1;
        END
    END TRY
    BEGIN CATCH
        EXEC sys.sp_set_session_context @key = N'S_disable_triggers', @value = @PreviousDisableTriggers, @read_only = 0;
        EXEC sys.sp_set_session_context @key = N'S_disable_notification_triggers', @value = @PreviousDisableNotificationTriggers, @read_only = 0;
        EXEC sys.sp_releaseapplock @Resource = @LockName, @LockOwner = N'Session';
        THROW;
    END CATCH

    EXEC sys.sp_releaseapplock @Resource = @LockName, @LockOwner = N'Session';

    SELECT
        LockAcquired     = CONVERT(bit, 1),
        QuotesExpired    = @QuotesExpired,
        EnquiriesExpired = @EnquiriesExpired,
        ExpiredSilently  = @ExpiredSilently,
        Failed           = (SELECT COUNT(1) FROM @Failures);

    SELECT f.RecordType, f.RecordGuid, f.ErrorMessage
    FROM @Failures AS f
    ORDER BY f.RecordType, f.RecordGuid;
END
GO

GO

/* Deploy StoredProcedure SSop.QuoteCreateJobs using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Procedures\SSop.QuoteCreateJobs.sql */
/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R7C4 selected DEV schema source sync
    Object             : StoredProcedure SSop.QuoteCreateJobs
    Source schema hash : 2D97A49F7C032824116D3F0DAA13A703C13B1D99C645007BB6B42C38C35C60B3
    Definition SHA-256 : 493B57FDCE3C1E690DF3EB696D3D5583796C7EC3E2987AC0DDDA78B0A39CEB54

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE OR ALTER PROCEDURE [SSop].[QuoteCreateJobs]
(
    @Guid UNIQUEIDENTIFIER
)
AS
BEGIN
    SET NOCOUNT ON;



-------------------------------------------------------------------------
-- Preconditions: Quote must be accepted
-- FIX: WF check must be scoped to THIS quote (dot.DataObjectGuid = @Guid)
-- FIX: semicolon before THROW
-------------------------------------------------------------------------
IF (
        NOT EXISTS
        (
            SELECT 1
            FROM SSop.EnquiryService_ExtendedInfo AS eex
            JOIN SSop.Quotes AS q ON (q.ID = eex.QuoteID)
            WHERE (q.Guid = @Guid)
              AND (eex.DateAccepted IS NOT NULL)
        )
        AND NOT EXISTS
        (
            SELECT 1
            FROM SCore.DataObjectTransition AS dot
            JOIN SCore.WorkflowStatus AS wfs ON (wfs.ID = dot.StatusID)
            WHERE (dot.DataObjectGuid = @Guid)                  -- << FIX
              AND (dot.RowStatus NOT IN (0,254))
              AND (wfs.Guid = '21A29AEE-2D99-4DA3-8182-F31813B0C498') -- Accepted
        )
   )
BEGIN
    ;THROW 60000, N'The quote must be accepted first', 1;
END;
PRINT N'Passed pre checks';
DECLARE @QuoteID INT = -1;
SELECT
    @QuoteID = q.ID
FROM SSop.Quotes AS q
WHERE q.Guid = @Guid
  AND q.RowStatus NOT IN (0, 254);
IF (@QuoteID <= 0)
BEGIN
    ;THROW 60000, N'Cannot create jobs because the supplied Quote Guid was not found or is inactive.', 1;
END;
-------------------------------------------------------------------------
-- Normalise empty Created Job values saved as 0. The Quote_JobsSummary
-- source treats CreatedJobId < 0 as not yet created.
-------------------------------------------------------------------------
UPDATE qi
SET
    qi.CreatedJobId = -1
FROM SSop.QuoteItems AS qi
JOIN SSop.Quotes AS q
    ON q.ID = qi.QuoteId
WHERE q.Guid = @Guid
  AND qi.RowStatus NOT IN (0, 254)
  AND qi.Quantity > 0
  AND ISNULL(qi.CreatedJobId, 0) = 0;
-------------------------------------------------------------------------
-- Build list of jobs to create
-------------------------------------------------------------------------
DECLARE @JobsToCreate TABLE
(
    ID INT NOT NULL PRIMARY KEY,
    Guid UNIQUEIDENTIFIER NOT NULL DEFAULT NEWID(),
    Net DECIMAL(19, 2) NOT NULL,
    RibaStage1Fee DECIMAL(19, 2) NOT NULL,
    RibaStage2Fee DECIMAL(19, 2) NOT NULL,
    RibaStage3Fee DECIMAL(19, 2) NOT NULL,
    RibaStage4Fee DECIMAL(19, 2) NOT NULL,
    RibaStage5Fee DECIMAL(19, 2) NOT NULL,
    RibaStage6Fee DECIMAL(19, 2) NOT NULL,
    RibaStage7Fee DECIMAL(19, 2) NOT NULL,
    PreConstructionStageFee DECIMAL(19, 2) NOT NULL,
    ConstructionStageFee DECIMAL(19, 2) NOT NULL,
    OrganisationalUnitGuid UNIQUEIDENTIFIER NOT NULL,
    JobTypeGuid UNIQUEIDENTIFIER NOT NULL,
    ContractGuid UNIQUEIDENTIFIER NOT NULL,
    IdentityGuid UNIQUEIDENTIFIER NOT NULL,
    QuoteItemId INT NOT NULL,
    ExternalReference NVARCHAR(50) NOT NULL,
    ValueOfWorkGuid UNIQUEIDENTIFIER NOT NULL,
    FeeCap DECIMAL(19, 2) NOT NULL,
    CurrentRibaStageGuid UNIQUEIDENTIFIER NOT NULL,
    TotalFee DECIMAL(19, 2) NOT NULL,
    AppointedFromStageGuid UNIQUEIDENTIFIER NOT NULL,
    CreatedJobID INT NOT NULL DEFAULT (-1),
    AgentContractGuid UNIQUEIDENTIFIER NOT NULL
);
DECLARE @JobPaymentStages TABLE
(
    Guid UNIQUEIDENTIFIER NOT NULL,
    JobId INT NOT NULL,
    StagedDate DATE NULL,
    AfterStageId INT NOT NULL,
    Value DECIMAL(19, 2) NOT NULL DEFAULT (0)
);
INSERT @JobsToCreate
(
    ID, Net,
    RibaStage1Fee, RibaStage2Fee, RibaStage3Fee, RibaStage4Fee, RibaStage5Fee, RibaStage6Fee, RibaStage7Fee,
    PreConstructionStageFee, ConstructionStageFee,
    OrganisationalUnitGuid, JobTypeGuid, ContractGuid, IdentityGuid,
    QuoteItemId, ExternalReference,
    ValueOfWorkGuid, FeeCap, CurrentRibaStageGuid, TotalFee, AppointedFromStageGuid, AgentContractGuid
)
SELECT
    js.ID,
    js.Net,
    js.RibaStage1Fee, js.RibaStage2Fee, js.RibaStage3Fee, js.RibaStage4Fee, js.RibaStage5Fee, js.RibaStage6Fee, js.RibaStage7Fee,
    js.PreConstructionStageFee, js.ConstructionStageFee,
    js.OrganisationalUnitGuid,
    js.JobTypeGuid,
    js.ContractGuid,
    js.IdentityGuid,
    js.QuoteItemId,
    js.ExternalReference,
    '00000000-0000-0000-0000-000000000000',
    js.FeeCap,
    js.CurrentRibaStageGuid,
    js.RibaStage1Fee + js.RibaStage2Fee + js.RibaStage3Fee + js.RibaStage4Fee + js.RibaStage5Fee
    + js.RibaStage6Fee + js.RibaStage7Fee + js.PreConstructionStageFee + js.ConstructionStageFee,
    js.AppointedRibaStageGuid,
    js.AgentContractGuid
FROM SSop.Quote_JobsSummary AS js
WHERE (js.QuoteGuid = @Guid)
  AND (
        js.DateAccepted IS NOT NULL
        OR EXISTS
        (
            SELECT 1
            FROM SCore.DataObjectTransition AS dot
            JOIN SCore.WorkflowStatus AS wfs ON (wfs.ID = dot.StatusID)
            WHERE dot.DataObjectGuid = @Guid
              AND dot.RowStatus NOT IN (0,254)
              AND wfs.Guid = '21A29AEE-2D99-4DA3-8182-F31813B0C498' -- Accepted
        )
        OR EXISTS
        (
            SELECT 1
            FROM SSop.EnquiryService_ExtendedInfo AS eex
            JOIN SSop.Quotes AS q ON (q.ID = eex.QuoteID)
            WHERE (q.Guid = @Guid)
              AND (eex.DateAccepted IS NOT NULL)
        )
      );
-------------------------------------------------------------------------
-- Load quote context required for job upserts
-------------------------------------------------------------------------
DECLARE
    @ClientAccountGuid    UNIQUEIDENTIFIER,
    @ClientAddressGuid    UNIQUEIDENTIFIER,
    @ClientContactGuid    UNIQUEIDENTIFIER,
    @AgentAccountGuid     UNIQUEIDENTIFIER,
    @AgentAddressGuid     UNIQUEIDENTIFIER,
    @AgentContactGuid     UNIQUEIDENTIFIER,
    @FinanceAccountGuid   UNIQUEIDENTIFIER,
    @FinanceAddressGuid   UNIQUEIDENTIFIER,
    @FinanceContactGuid   UNIQUEIDENTIFIER,
    @StructureGuid        UNIQUEIDENTIFIER,
    @ProjectGuid          UNIQUEIDENTIFIER,
    @Overview             NVARCHAR(1000),
    @ValueOfWork          DECIMAL(19, 2),
    @IsNDA                BIT,
    @DataClassificationGuid     UNIQUEIDENTIFIER,
    @SecurityClassificationGuid UNIQUEIDENTIFIER,
	@SectorId			  INT,
	@MarketId			  INT;
SELECT
    @ClientAccountGuid  = CASE WHEN ca.Guid = '00000000-0000-0000-0000-000000000000' THEN extClienttacc.Guid ELSE ca.Guid END,
    @ClientAddressGuid  = CASE WHEN caa.Guid = '00000000-0000-0000-0000-000000000000' THEN extClientadd.Guid ELSE caa.Guid END,
    @ClientContactGuid  = CASE WHEN cac.Guid = '00000000-0000-0000-0000-000000000000' THEN extClientCont.Guid ELSE cac.Guid END,
    @AgentAccountGuid   = CASE WHEN aa.Guid = '00000000-0000-0000-0000-000000000000' THEN extagentacc.Guid ELSE aa.Guid END,
    @AgentAddressGuid   = CASE WHEN aaa.Guid = '00000000-0000-0000-0000-000000000000' THEN extagentadd.Guid ELSE aaa.Guid END,
    @AgentContactGuid   = CASE WHEN aac.Guid = '00000000-0000-0000-0000-000000000000' THEN extagentCont.Guid ELSE aac.Guid END,
    @FinanceAccountGuid = CASE WHEN fa.Guid = '00000000-0000-0000-0000-000000000000' THEN extFinanceacc.Guid ELSE fa.Guid END,
    @FinanceAddressGuid = CASE WHEN faa.Guid = '00000000-0000-0000-0000-000000000000' THEN extFinanceadd.Guid ELSE faa.Guid END,
    @FinanceContactGuid = CASE WHEN fac.Guid = '00000000-0000-0000-0000-000000000000' THEN extFinanceCont.Guid ELSE fac.Guid END,
    @StructureGuid      = CASE WHEN p.Guid = '00000000-0000-0000-0000-000000000000' THEN extAsset.Guid ELSE p.Guid END,
    @ProjectGuid        = p2.Guid,
    @Overview           = CASE WHEN q.DescriptionOfWorks = '' THEN e.DescriptionOfWorks ELSE q.DescriptionOfWorks END,
    @ValueOfWork        = e.ValueOfWork,
    @IsNDA              = e.IsSubjectToNDA,
    @DataClassificationGuid     = dc.Guid,
    @SecurityClassificationGuid = sc.Guid,
	@SectorId			= q.SectorId,
	@MarketId           = q.MarketId
FROM SSop.Quotes AS q
JOIN SSop.Quote_ExtendedInfo AS qei ON (qei.Id = q.ID)
JOIN SCrm.Accounts AS ca ON (ca.ID = q.ClientAccountID)
JOIN SCrm.AccountAddresses AS caa ON (caa.ID = q.ClientAddressId)
JOIN SCrm.AccountContacts AS cac ON (cac.ID = q.ClientContactId)
JOIN SCrm.Accounts AS aa ON (aa.ID = q.AgentAccountId)
JOIN SCrm.AccountAddresses AS aaa ON (aaa.ID = q.AgentAddressId)
JOIN SCrm.AccountContacts AS aac ON (aac.ID = q.AgentContactId)
JOIN SCrm.Accounts AS fa ON (fa.ID = qei.FinanceAccountId)
JOIN SCrm.AccountAddresses AS faa ON (faa.ID = qei.FinanceAddressId)
JOIN SCrm.AccountContacts AS fac ON (fac.ID = qei.FinanceContactId)
JOIN SJob.Assets AS p ON (p.ID = qei.PropertyId)
JOIN SSop.Projects AS p2 ON (p2.ID = q.ProjectId)
JOIN SSop.EnquiryServices AS es ON (es.ID = q.EnquiryServiceID)
JOIN SSop.Enquiries AS e ON (e.ID = es.EnquiryId)
LEFT JOIN SCrm.Accounts extagentacc ON (extagentacc.ID = qei.AgentAccountID)
LEFT JOIN SCrm.AccountAddresses extagentadd ON (extagentadd.ID = qei.AgentAddressId)
LEFT JOIN SCrm.AccountContacts extagentCont ON (extagentCont.ID = qei.AgentAccountContactId)
LEFT JOIN SCrm.Accounts extClienttacc ON (extClienttacc.ID = qei.ClientAccountID)
LEFT JOIN SCrm.AccountAddresses extClientadd ON (extClientadd.ID = qei.ClientAddressId)
LEFT JOIN SCrm.AccountContacts extClientCont ON (extClientCont.ID = qei.ClientAccountContactId)
LEFT JOIN SCrm.Accounts extFinanceacc ON (extFinanceacc.ID = qei.FinanceAccountId)
LEFT JOIN SCrm.AccountAddresses extFinanceadd ON (extFinanceadd.ID = qei.FinanceAddressId)
LEFT JOIN SCrm.AccountContacts extFinanceCont ON (extFinanceCont.ID = qei.FinanceContactId)
LEFT JOIN SJob.Assets extAsset ON (extAsset.ID = qei.PropertyId)
LEFT JOIN SCore.DataClassifications AS dc ON dc.ID = q.DataClassificationID AND dc.RowStatus NOT IN (0, 254)
LEFT JOIN SCore.SecurityClassifications AS sc ON sc.ID = q.SecurityClassificationID AND sc.RowStatus NOT IN (0, 254)
WHERE (q.Guid = @Guid);
IF (@DataClassificationGuid IS NULL)
BEGIN
    ;THROW 60000, N'Cannot create job from quote because the quote Data Classification could not be resolved to an active SCore.DataClassifications row.', 1;
END;
IF (@SecurityClassificationGuid IS NULL)
BEGIN
    ;THROW 60000, N'Cannot create job from quote because the quote Security Classification could not be resolved to an active SCore.SecurityClassifications row.', 1;
END;
IF NOT EXISTS (SELECT 1 FROM @JobsToCreate)
BEGIN
    ;THROW 60000, N'There were no jobs to create', 1;
END;
-------------------------------------------------------------------------
-- Create jobs
-------------------------------------------------------------------------
DECLARE
    @CreatedDateTime         DATETIME2 = GETUTCDATE(),
    @JobGuid                 UNIQUEIDENTIFIER,
    @OrganisationalUnitGuid  UNIQUEIDENTIFIER,
    @JobTypeGuid             UNIQUEIDENTIFIER,
    @ContractGuid            UNIQUEIDENTIFIER,
    @ValueOfWorkGuid         UNIQUEIDENTIFIER,
    @RibaStage1Fee           DECIMAL(19, 2),
    @RibaStage2Fee           DECIMAL(19, 2),
    @RibaStage3Fee           DECIMAL(19, 2),
    @RibaStage4Fee           DECIMAL(19, 2),
    @RibaStage5Fee           DECIMAL(19, 2),
    @RibaStage6Fee           DECIMAL(19, 2),
    @RibaStage7Fee           DECIMAL(19, 2),
    @PreConstructionStageFee DECIMAL(19, 2),
    @ConstructionStageFee    DECIMAL(19, 2),
    @ExternalReference       NVARCHAR(50),
    @MaxID                   INT,
    @CurrentId               INT,
    @QuoteItemID             INT,
    @CreatedJobID            INT,
    @FeeCap                  DECIMAL(19, 2),
    @CurrentRibaStageGuid    UNIQUEIDENTIFIER,
    @AppointedRibaStageGuid  UNIQUEIDENTIFIER,
    @AgentContractGuid       UNIQUEIDENTIFIER,
    @CompleteForReviewDate   DATETIME2,
	@SectorGuid				 UNIQUEIDENTIFIER,
	@MarketGuid				 UNIQUEIDENTIFIER
SELECT
    @MaxID = MAX(ID),
    @CurrentId = 0
FROM @JobsToCreate;
SELECT @SectorGuid = Guid
FROM SCore.Sectors
WHERE (ID = @SectorId)
SELECT @MarketGuid = Guid
FROM SCore.Markets
WHERE (ID = @MarketId)
PRINT N'Creating job(s)';
WHILE (@CurrentId < @MaxID)
BEGIN
    SELECT TOP (1)
        @CurrentId               = j.ID,
        @OrganisationalUnitGuid  = j.OrganisationalUnitGuid,
        @JobTypeGuid             = j.JobTypeGuid,
        @ContractGuid            = j.ContractGuid,
        @ExternalReference       = j.ExternalReference,
        @QuoteItemID             = j.QuoteItemId,
        @ValueOfWorkGuid         = j.ValueOfWorkGuid,
        @RibaStage1Fee           = j.RibaStage1Fee,
        @RibaStage2Fee           = j.RibaStage2Fee,
        @RibaStage3Fee           = j.RibaStage3Fee,
        @RibaStage4Fee           = j.RibaStage4Fee,
        @RibaStage5Fee           = j.RibaStage5Fee,
        @RibaStage6Fee           = j.RibaStage6Fee,
        @RibaStage7Fee           = j.RibaStage7Fee,
        @PreConstructionStageFee = j.PreConstructionStageFee,
        @ConstructionStageFee    = j.ConstructionStageFee,
        @FeeCap                  = j.FeeCap,
        @CurrentRibaStageGuid    = j.CurrentRibaStageGuid,
        @AppointedRibaStageGuid  = j.AppointedFromStageGuid,
        @JobGuid                 = j.Guid,
        @AgentContractGuid       = j.AgentContractGuid,   -- << FIX
        @CompleteForReviewDate   = NULL
    FROM @JobsToCreate AS j
    WHERE (j.ID > @CurrentId)
    ORDER BY j.ID;
    -- Ensure Jobs security enforcement can derive OrgUnit from the SOURCE Quote
    EXEC sys.sp_set_session_context
        @key = N'new_entity_type_guid',
        @value = '63542427-46AB-4078-ABD1-1D583C24315C', -- Jobs EntityTypeGuid
        @read_only = 0;
    EXEC sys.sp_set_session_context
        @key = N'record_guid',
        @value = @Guid, -- QuoteGuid (source record)
        @read_only = 0;
    -- IMPORTANT: create Job as "New"
    -- Do NOT set JobStarted datetime during creation.
    EXEC SJob.JobsUpsert
         @OrganisationalUnitGuid      = @OrganisationalUnitGuid,
         @JobTypeGuid                 = @JobTypeGuid,
         @UprnGuid                    = @StructureGuid,
         @ClientAccountGuid           = @ClientAccountGuid,
         @ClientAddressGuid           = @ClientAddressGuid,
         @ClientContactGuid           = @ClientContactGuid,
         @AgentAccountGuid            = @AgentAccountGuid,
         @AgentAddressGuid            = @AgentAddressGuid,
         @AgentContactGuid            = @AgentContactGuid,
         @SurveyorGuid                = '00000000-0000-0000-0000-000000000000',
         @JobDescription              = @Overview,
         @IsSubjectToNDA              = @IsNDA,
         @JobStarted                  = NULL,              -- << FIX (was setting datetime)
         @JobCompleted                = NULL,
         @JobCancelled                = NULL,
         @ValueOfWorkGuid             = @ValueOfWorkGuid,
         @RibaStage1Fee               = @RibaStage1Fee,
         @RibaStage2Fee               = @RibaStage2Fee,
         @RibaStage3Fee               = @RibaStage3Fee,
         @RibaStage4Fee               = @RibaStage4Fee,
         @RibaStage5Fee               = @RibaStage5Fee,
         @RibaStage6Fee               = @RibaStage6Fee,
         @RibaStage7Fee               = @RibaStage7Fee,
         @PreConstructionStageFee     = @PreConstructionStageFee,
         @ConstructionStageFee        = @ConstructionStageFee,
         @FeeCap                      = @FeeCap,
         @CurrentRibaStageGuid        = @CurrentRibaStageGuid,
         @JobDormant                  = NULL,
         @AgreedFee                   = 0,
         @AppFormReceived             = FALSE,
         @ArchiveReferenceLink        = N'',
         @ArchiveBoxReference         = N'',
         @CreatedOn                   = @CreatedDateTime,
         @ExternalReference           = @ExternalReference,
         @IsCompleteForReview         = 0,
         @ReviewedByUserGuid          = '00000000-0000-0000-0000-000000000000',
         @ReviewDateTimeUTC           = NULL,
         @FinanceAccountGuid          = @FinanceAccountGuid,
         @FinanceAddressGuid          = @FinanceAddressGuid,
         @FinanceContactGuid          = @FinanceContactGuid,
         @PurchaseOrderNumber         = N'',
         @ContractGuid                = @ContractGuid,
         @ProjectGuid                 = @ProjectGuid,
         @ValueOfWork                 = @ValueOfWork,
         @ClientAppointmentReceived   = 0,
         @AppointedFromStageGuid      = @AppointedRibaStageGuid,
         @DeadDate                    = NULL,
         @Guid                        = @JobGuid,
         @BillingInstruction          = NULL,
         @CannotBeInvoiced            = 0,
         @CannotBeInvoicedReason      = N'',
         @AgentContractGuid           = @AgentContractGuid,
         @CompleteForReviewDate       = @CompleteForReviewDate,
		 @SectorGuid				  = @SectorGuid,
		 @MarketGuid				  = @MarketGuid,
         @DataClassificationGuid     = @DataClassificationGuid,
         @SecurityClassificationGuid = @SecurityClassificationGuid
    EXEC sys.sp_set_session_context @key = N'new_entity_type_guid', @value = NULL, @read_only = 0;
    EXEC sys.sp_set_session_context @key = N'record_guid',         @value = NULL, @read_only = 0;
    SELECT @CreatedJobID = ID
    FROM SJob.Jobs
    WHERE (Guid = @JobGuid);
    UPDATE @JobsToCreate
    SET CreatedJobID = @CreatedJobID
    WHERE (ID = @CurrentId);
    INSERT INTO @JobPaymentStages (Guid, JobId, StagedDate, AfterStageId, Value)
    SELECT
        sps.Guid,
        jtc.CreatedJobID,
        sps.StagedDate,
        sps.AfterStageId,
        sps.Value
    FROM SSop.Quotes_StagedPaymentSummary(@Guid) AS sps
    JOIN @JobsToCreate AS jtc ON (sps.JobId = jtc.ID)
    WHERE (jtc.ID = @CurrentId);
    PRINT N'Created job';
    IF (@QuoteItemID > 0)
    BEGIN
        UPDATE SSop.QuoteItems
        SET CreatedJobId = @CreatedJobID
        WHERE (ID = @QuoteItemID);
    END
    ELSE
    BEGIN
        UPDATE qi
        SET qi.CreatedJobId = @CreatedJobID
        FROM SSop.QuoteItems AS qi
        JOIN SProd.Products AS p ON (p.ID = qi.ProductId)
        JOIN SSop.Quotes AS q ON (q.ID = qi.QuoteId)
        JOIN SSop.EnquiryServices AS es ON (es.ID = q.EnquiryServiceID)
        JOIN SJob.JobTypes AS jt ON (jt.ID = CASE WHEN p.CreatedJobType > 0 THEN p.CreatedJobType ELSE es.JobTypeId END)
        WHERE (jt.Guid = @JobTypeGuid)
          AND (q.Guid = @Guid)
          AND (p.NeverConsolidate = 0)
          AND (qi.DoNotConsolidateJob = 0)
          AND (qi.RowStatus NOT IN (0, 254))
          AND (qi.CreatedJobId <= 0);
    END;
    -------------------------------------------------------------------------
    -- CYB-438: Quote-to-Job invoice schedule normalisation.
    -- This must run after CreatedJobId has been written to the quote items,
    -- because the Job invoice schedule grid resolves schedules via
    -- SSop.QuoteItems.CreatedJobId + SSop.QuoteItems.InvoicingSchedule.
    -------------------------------------------------------------------------
    DECLARE @MissingQuoteItemScheduleCount INT = 0;
    DECLARE @ManualInvoiceScheduleId INT = -1;
    DECLARE @ManualInvoiceScheduleGuid UNIQUEIDENTIFIER = NULL;
    DECLARE @ManualTriggerGuid UNIQUEIDENTIFIER = NULL;
    SELECT
        @MissingQuoteItemScheduleCount = COUNT_BIG(1)
    FROM SSop.QuoteItems AS qi
    WHERE qi.RowStatus NOT IN (0, 254)
      AND qi.CreatedJobId = @CreatedJobID
      AND ISNULL(qi.InvoicingSchedule, -1) IN (-1, 0);
    IF (@MissingQuoteItemScheduleCount > 0)
    BEGIN
        -- Re-use a system-generated Manual schedule only when it is already
        -- linked to one of this Job's quote items. SFin.InvoiceSchedules is
        -- quote-scoped, so re-using an unrelated quote-level schedule would
        -- incorrectly join separate created jobs together in the Job grid.
        SELECT TOP (1)
            @ManualInvoiceScheduleId = invs.ID
        FROM SSop.QuoteItems AS qi
        JOIN SFin.InvoiceSchedules AS invs
            ON invs.ID = qi.InvoicingSchedule
           AND invs.RowStatus NOT IN (0, 254)
        JOIN SFin.InvoiceScheduleTrigger AS ist
            ON ist.ID = invs.TriggerId
           AND ist.RowStatus NOT IN (0, 254)
        WHERE qi.RowStatus NOT IN (0, 254)
          AND qi.CreatedJobId = @CreatedJobID
          AND invs.QuoteId = @QuoteID
          AND invs.Name = N'Manual'
          AND invs.DescriptionOfWork = N'System generated manual invoice schedule created during job creation.'
          AND ist.Name = N'Manual'
        ORDER BY invs.ID;
        IF (ISNULL(@ManualInvoiceScheduleId, -1) <= 0)
        BEGIN
            SELECT TOP (1)
                @ManualTriggerGuid = ist.Guid
            FROM SFin.InvoiceScheduleTrigger AS ist
            WHERE ist.RowStatus NOT IN (0, 254)
              AND ist.Name = N'Manual'
            ORDER BY ist.ID;
            IF (@ManualTriggerGuid IS NULL)
            BEGIN
                ;THROW 60000, N'Could not resolve the Manual invoice schedule trigger.', 1;
            END;
            SET @ManualInvoiceScheduleGuid = NEWID();
            EXEC SFin.InvoiceSchedulesUpsert
                 @Guid                            = @ManualInvoiceScheduleGuid,
                 @Name                            = N'Manual',
                 @TriggerGuid                     = @ManualTriggerGuid,
                 @ExpectedDate                    = NULL,
                 @DescriptionOfWork               = N'System generated manual invoice schedule created during job creation.',
                 @Amount                          = 0,
                 @QuoteGuid                       = @Guid,
                 @RibaOnCompletion                = 0,
                 @RibaOnPartCompletion            = 0,
                 @OnMilestoneCompletion           = 0,
                 @OnActivityCompletion            = 0,
                 @OnActivityAndMilestonCompletion = 0,
                 @ScheduleReenabled               = 0;
            SELECT
                @ManualInvoiceScheduleId = invs.ID
            FROM SFin.InvoiceSchedules AS invs
            WHERE invs.Guid = @ManualInvoiceScheduleGuid
              AND invs.RowStatus NOT IN (0, 254);
            IF (ISNULL(@ManualInvoiceScheduleId, -1) <= 0)
            BEGIN
                ;THROW 60000, N'Failed to create the system generated Manual invoice schedule for the created Job.', 1;
            END;
        END;
        UPDATE qi
        SET qi.InvoicingSchedule = @ManualInvoiceScheduleId
        FROM SSop.QuoteItems AS qi
        WHERE qi.RowStatus NOT IN (0, 254)
          AND qi.CreatedJobId = @CreatedJobID
          AND ISNULL(qi.InvoicingSchedule, -1) IN (-1, 0);
    END;
    -------------------------------------------------------------------------
    -- CYB-438: Initial invoice processing mode.
    -- 0 = Automated, 1 = Manual, 2 = Paused.
    -- Any active non-Manual schedule linked to the created Job makes the Job
    -- automated. A Job is Manual only when every linked schedule is Manual.
    -------------------------------------------------------------------------
    DECLARE @TargetInvoiceProcessingMode TINYINT = 1;
    DECLARE @InvoiceModeReason NVARCHAR(500) = N'Quote item converted without assigned automated invoice schedule; defaulted to Manual invoice mode.';
    IF EXISTS
    (
        SELECT 1
        FROM SSop.QuoteItems AS qi
        JOIN SFin.InvoiceSchedules AS invs
            ON invs.ID = qi.InvoicingSchedule
           AND invs.RowStatus NOT IN (0, 254)
        JOIN SFin.InvoiceScheduleTrigger AS ist
            ON ist.ID = invs.TriggerId
           AND ist.RowStatus NOT IN (0, 254)
        WHERE qi.RowStatus NOT IN (0, 254)
          AND qi.CreatedJobId = @CreatedJobID
          AND ISNULL(qi.InvoicingSchedule, -1) NOT IN (-1, 0)
          AND ISNULL(ist.Name, N'') <> N'Manual'
    )
    BEGIN
        SET @TargetInvoiceProcessingMode = 0;
        SET @InvoiceModeReason = N'Quote item converted with an assigned automated invoice schedule; defaulted to Automated invoice mode.';
    END;
    EXEC SFin.JobInvoiceProcessingMode_Set
         @JobGuid = @JobGuid,
         @NewMode = @TargetInvoiceProcessingMode,
         @ChangedByUserGuid = NULL,
         @Reason = @InvoiceModeReason,
         @Source = N'QuoteCreateJobs';
    -------------------------------------------------------------------------
    -- Write the Job's per-stage agreed fees (SJob.JobRibaStageFees) as part of
    -- creating the Job. The fixed fee columns above have no Stage 0 or custom
    -- stage slot, so without these rows a Stage 0 quote item creates a Job
    -- with a zero agreed fee (e.g. Job 9615). Runs after the invoice schedule
    -- normalisation above because the stage values honour the schedule.
    -- Idempotent: SSop.QuoteCreateJobs_WithInvoiceScheduleStageValidation
    -- re-running it for the same Job only re-applies the same values.
    -------------------------------------------------------------------------
    EXEC SJob.JobRibaStageFees_UpsertFromCreatedQuoteItems @JobID = @CreatedJobID;
    EXEC SJob.JobActivitiesBuildFromTemplate @JobID = @CreatedJobID;
END;
-------------------------------------------------------------------------
-- Bulk upsert JobPaymentStages (preserved)
-------------------------------------------------------------------------
DECLARE @GuidList SCore.GuidUniqueList,
        @IsInsert BIT;
PRINT N'Creating staged payments';
DELETE FROM @GuidList;
INSERT INTO @GuidList (GuidValue)
SELECT Guid
FROM @JobPaymentStages;
EXEC SCore.DataObjectBulkUpsert
     @GuidList   = @GuidList,
     @SchemeName = N'SJob',
     @ObjectName = N'JobPaymentStages',
     @IsInsert   = @IsInsert;
INSERT INTO SJob.JobPaymentStages (RowStatus, Guid, JobId, StagedDate, AfterStageId, Value)
SELECT
    1,
    jps.Guid,
    jps.JobId,
    jps.StagedDate,
    jps.AfterStageId,
    jps.Value
FROM @JobPaymentStages AS jps;
PRINT N'Staged Payments Created';
-------------------------------------------------------------------------
-- NEW: Move Quote WF to "Complete" after successful job creation
-- IMPORTANT: follow your rule: UpsertDataObject first, then TransitionUpsert
-------------------------------------------------------------------------
DECLARE @CompleteQuoteStatusGuid UNIQUEIDENTIFIER = NULL;
SELECT TOP (1) @CompleteQuoteStatusGuid = ws.Guid
FROM SCore.WorkflowStatus ws
WHERE ws.RowStatus NOT IN (0,254)
  AND ws.ShowInQuotes = 1
  AND ws.Name = N'Complete'
ORDER BY ws.ID;
IF (@CompleteQuoteStatusGuid IS NOT NULL)
BEGIN
    DECLARE @LatestQuoteStatusGuid UNIQUEIDENTIFIER = NULL;
    SELECT TOP (1) @LatestQuoteStatusGuid = wfs.Guid
    FROM SCore.DataObjectTransition dot
    JOIN SCore.WorkflowStatus wfs ON wfs.ID = dot.StatusID
    WHERE dot.DataObjectGuid = @Guid
      AND dot.RowStatus NOT IN (0,254)
      AND wfs.RowStatus NOT IN (0,254)
    ORDER BY dot.DateTimeUTC DESC, dot.ID DESC;
    IF (@LatestQuoteStatusGuid IS NULL OR @LatestQuoteStatusGuid <> @CompleteQuoteStatusGuid)
    BEGIN
        DECLARE @QuoteCompleteTransitionGuid UNIQUEIDENTIFIER = NEWID();
        DECLARE @TransitionIsInsert BIT = 0;
        -- Ensure DataObject exists FIRST (your rule)
        EXEC SCore.UpsertDataObject
            @Guid       = @QuoteCompleteTransitionGuid,
            @SchemeName = N'SCore',
            @ObjectName = N'DataObjectTransition',
            @IsInsert   = @TransitionIsInsert OUTPUT;
        -- Now write the transition
        EXEC SCore.DataObjectTransitionUpsert
            @Guid             = @QuoteCompleteTransitionGuid,
            @OldStatusGuid     = '00000000-0000-0000-0000-000000000000',
            @StatusGuid        = @CompleteQuoteStatusGuid,
            @Comment           = N'System Imported (Job creation).',
            @CreatedByUserGuid = '00000000-0000-0000-0000-000000000000',
            @SurveyorUserGuid  = '00000000-0000-0000-0000-000000000000',
            @DataObjectGuid    = @Guid,
            @IsImported        = 1;
        PRINT N'Quote moved to Complete';
    END
END
ELSE
BEGIN
    PRINT N'WARNING: Could not resolve Quote "Complete" workflow status (ShowInQuotes=1, Name=Complete).';
END
END;
GO

